var n=`0914-jiaozi`;var a=`world-0914`;var t=`CN`;var o=`east-asia`;var s=8;var l=70;var r={en:`Jiaozi`,ua:`Цзяоцзи`};var g={en:`Jiaozi is a China dish made with all-purpose flour, ground pork, napa cabbage, green onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Цзяоцзи, страва кухні країни Китай. Основні складники: пшеничне борошно універсальне, свинячий фарш, пекінська капуста, зелена цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,400,`g`],[`water`,215,`ml`],[`table-salt`,5,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-pork`,430,`g`],[`napa-cabbage`,280,`g`],[`green-onion`,85,`g`],[`ground-ginger`,18,`g`],[`light-soy-sauce`,35,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:25,i:[]},{en:`Pinch the dumplings tightly and boil in batches until the pork filling is thoroughly cooked; split one to check.`,ua:`Ретельно защипніть пельмені й варіть партіями до повної готовності свинячого фаршу; розріжте один для перевірки.`,t:[`boiling`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`black-rice-vinegar`,55,`ml`],[`sesame-oil`,15,`ml`]]}];var h={slug:n,id:a,country:`CN`,region:o,servings:8,minutes:70,title:r,text:g,steps:d};export{t as country,h as default,a as id,l as minutes,o as region,s as servings,n as slug,d as steps,g as text,r as title};